  "Kanpur South": { hi: "कानपुर दक्षिण", mr: "कानपूर दक्षिण", ta: "கான்பூர் தெற்கு", te: "కాన్పూర్ దక్షిణ", kn: "ಕಾನ್ಪುರ ದಕ್ಷಿಣ" },
