  "Yesterday, 6:10 PM": { hi: "कल, शाम 6:10", mr: "काल, संध्याकाळी 6:10", ta: "நேற்று, மாலை 6:10", te: "నిన్న, సాయంత్రం 6:10", kn: "ನಿನ್ನೆ, ಸಂಜೆ 6:10" },
  "Today, 8:05 AM": { hi: "आज, सुबह 8:05", mr: "आज, सकाळी 8:05", ta: "இன்று, காலை 8:05", te: "ఈరోజు, ఉదయం 8:05", kn: "ಇಂದು, ಬೆಳಗ್ಗೆ 8:05" },
  "Manage your personal settings and account actions": { hi: "अपनी व्यक्तिगत सेटिंग और खाता कार्रवाइयाँ संभालें", mr: "तुमच्या वैयक्तिक सेटिंग्ज आणि खाते कृती व्यवस्थापित करा", ta: "உங்கள் தனிப்பட்ட அமைப்புகளையும் கணக்கு செயல்களையும் நிர்வகிக்கவும்", te: "మీ వ్యక్తిగత సెట్టింగ్‌లు మరియు ఖాతా చర్యలను నిర్వహించండి", kn: "ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಮತ್ತು ಖಾತೆ ಕ್ರಮಗಳನ್ನು ನಿರ್ವಹಿಸಿ" },
  "NeedMap User": { hi: "NeedMap उपयोगकर्ता", mr: "NeedMap वापरकर्ता", ta: "NeedMap பயனர்", te: "NeedMap వినియోగదారు", kn: "NeedMap ಬಳಕೆದಾರ" },
  "Profile for": { hi: "प्रोफाइल", mr: "प्रोफाइल", ta: "சுயவிவரம்", te: "ప్రొఫైల్", kn: "ಪ್ರೊಫೈಲ್" },
  "role": { hi: "भूमिका", mr: "भूमिका", ta: "பங்கு", te: "పాత్ర", kn: "ಪಾತ್ರ" },
  "No email": { hi: "ईमेल नहीं", mr: "ईमेल नाही", ta: "மின்னஞ்சல் இல்லை", te: "ఈమెయిల్ లేదు", kn: "ಇಮೇಲ್ ಇಲ್ಲ" },
  "Upload Profile Photo": { hi: "प्रोफाइल फोटो अपलोड करें", mr: "प्रोफाइल फोटो अपलोड करा", ta: "சுயவிவர புகைப்படம் பதிவேற்றவும்", te: "ప్రొఫైల్ ఫోటో అప్లోడ్ చేయండి", kn: "ಪ್ರೊಫೈಲ್ ಫೋಟೋ ಅಪ್ಲೋಡ್ ಮಾಡಿ" },
  "Accessibility": { hi: "सुगम्यता", mr: "सुलभता", ta: "அணுகல்தன்மை", te: "ప్రాప్యత", kn: "ಪ್ರವೇಶಸೌಲಭ್ಯ" },
  "Choose display, motion, and assistive support that works best for you. These settings apply across every role and page.": { hi: "अपने लिए सबसे अच्छा प्रदर्शन, गति और सहायक समर्थन चुनें। ये सेटिंग हर भूमिका और पेज पर लागू होती हैं।", mr: "तुमच्यासाठी योग्य डिस्प्ले, हालचाल आणि सहाय्यक समर्थन निवडा. या सेटिंग्ज प्रत्येक भूमिका आणि पानावर लागू होतात.", ta: "உங்களுக்கு ஏற்ற காட்சி, இயக்கம் மற்றும் உதவி ஆதரவைத் தேர்வுசெய்க. இவை ஒவ்வொரு பங்கிலும் பக்கத்திலும் செயல்படும்.", te: "మీకు సరిపోయే ప్రదర్శన, చలనం మరియు సహాయక మద్దతును ఎంచుకోండి. ఇవి ప్రతి పాత్ర మరియు పేజీలో వర్తిస్తాయి.", kn: "ನಿಮಗೆ ಸರಿಹೊಂದುವ ಪ್ರದರ್ಶನ, ಚಲನೆ ಮತ್ತು ಸಹಾಯಕ ಬೆಂಬಲವನ್ನು ಆಯ್ಕೆಮಾಡಿ. ಇವು ಪ್ರತಿಯೊಂದು ಪಾತ್ರ ಮತ್ತು ಪುಟದಲ್ಲಿ ಅನ್ವಯಿಸುತ್ತವೆ." },
  "Use device accessibility": { hi: "डिवाइस सुगम्यता उपयोग करें", mr: "डिव्हाइस सुलभता वापरा", ta: "சாதன அணுகல்தன்மை பயன்படுத்து", te: "పరికర ప్రాప్యతను ఉపయోగించండి", kn: "ಸಾಧನ ಪ್ರವೇಶಸೌಲಭ್ಯ ಬಳಸಿ" },
  "Follows screen reader, reduce motion, bold text, invert colors, and high contrast settings from your device.": { hi: "आपके डिवाइस की स्क्रीन रीडर, कम गति, बोल्ड टेक्स्ट, रंग उलटने और हाई कंट्रास्ट सेटिंग का पालन करता है।", mr: "तुमच्या डिव्हाइसवरील स्क्रीन रीडर, कमी हालचाल, ठळक मजकूर, रंग उलटणे आणि उच्च कॉन्ट्रास्ट सेटिंग्ज पाळते.", ta: "உங்கள் சாதனத்தின் திரைவாசிப்பு, இயக்கக் குறைப்பு, தடித்த எழுத்து, நிற மாற்றம் மற்றும் உயர் மாறுபாடு அமைப்புகளை பின்பற்றும்.", te: "మీ పరికరంలోని స్క్రీన్ రీడర్, చలనం తగ్గింపు, బోల్డ్ టెక్స్ట్, రంగు మార్పు మరియు అధిక కాంట్రాస్ట్ సెట్టింగ్‌లను అనుసరిస్తుంది.", kn: "ನಿಮ್ಮ ಸಾಧನದ ಸ್ಕ್ರೀನ್ ರೀಡರ್, ಚಲನೆ ಕಡಿತ, ದಪ್ಪ ಪಠ್ಯ, ಬಣ್ಣ ತಿರುಗು ಮತ್ತು ಹೈ ಕಾಂಟ್ರಾಸ್ಟ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಅನುಸರಿಸುತ್ತದೆ." },
  "Current device accessibility status": { hi: "वर्तमान डिवाइस सुगम्यता स्थिति", mr: "सध्याची डिव्हाइस सुलभता स्थिती", ta: "தற்போதைய சாதன அணுகல்தன்மை நிலை", te: "ప్రస్తుత పరికర ప్రాప్యత స్థితి", kn: "ಪ್ರಸ್ತುತ ಸಾಧನ ಪ್ರವೇಶಸೌಲಭ್ಯ ಸ್ಥಿತಿ" },
  "Device status": { hi: "डिवाइस स्थिति", mr: "डिव्हाइस स्थिती", ta: "சாதன நிலை", te: "పరికర స్థితి", kn: "ಸಾಧನ ಸ್ಥಿತಿ" },
  "Screen reader": { hi: "स्क्रीन रीडर", mr: "स्क्रीन रीडर", ta: "திரைவாசிப்பு", te: "స్క్రీన్ రీడర్", kn: "ಸ್ಕ್ರೀನ್ ರೀಡರ್" },
