  "Bold text": { hi: "बोल्ड टेक्स्ट", mr: "ठळक मजकूर", ta: "தடித்த எழுத்து", te: "బోల్డ్ టెక్స్ట్", kn: "ದಪ್ಪ ಪಠ್ಯ" },
  "Invert/high contrast": { hi: "रंग उलटें/हाई कंट्रास्ट", mr: "रंग उलट/उच्च कॉन्ट्रास्ट", ta: "நிற மாற்றம்/உயர் மாறுபாடு", te: "రంగు మార్పు/అధిక కాంట్రాస్ట్", kn: "ಬಣ್ಣ ತಿರುಗು/ಹೈ ಕಾಂಟ್ರಾಸ್ಟ್" },
