  "Set text size to": { hi: "टेक्स्ट आकार सेट करें", mr: "मजकूर आकार सेट करा", ta: "உரை அளவை அமை", te: "టెక్స్ట్ పరిమాణాన్ని సెట్ చేయండి", kn: "ಪಠ್ಯ ಗಾತ್ರವನ್ನು ಹೊಂದಿಸಿ" },
  "Normal": { hi: "सामान्य", mr: "सामान्य", ta: "சாதாரண", te: "సాధారణ", kn: "ಸಾಮಾನ್ಯ" },
  "Large": { hi: "बड़ा", mr: "मोठा", ta: "பெரியது", te: "పెద్ద", kn: "ದೊಡ್ಡದು" },
  "Extra Large": { hi: "बहुत बड़ा", mr: "अतिरिक्त मोठा", ta: "மிகப் பெரியது", te: "చాలా పెద్ద", kn: "ಅತ್ಯಂತ ದೊಡ್ಡದು" },
  "High contrast": { hi: "हाई कंट्रास्ट", mr: "उच्च कॉन्ट्रास्ट", ta: "உயர் மாறுபாடு", te: "అధిక కాంట్రాస్ట్", kn: "ಹೈ ಕಾಂಟ್ರಾಸ್ಟ್" },
  "Uses stronger borders and brighter foreground colors.": { hi: "मजबूत बॉर्डर और चमकीले अग्रभूमि रंग उपयोग करता है।", mr: "मजबूत सीमा आणि उजळ पुढील रंग वापरते.", ta: "வலுவான எல்லைகள் மற்றும் தெளிவான முன்புற நிறங்களைப் பயன்படுத்தும்.", te: "బలమైన అంచులు మరియు ప్రకాశవంతమైన ముందుభాగ రంగులను ఉపయోగిస్తుంది.", kn: "ಬಲವಾದ ಗಡಿಗಳು ಮತ್ತು ಹೆಚ್ಚು ಸ್ಪಷ್ಟ ಮುಂಭಾಗದ ಬಣ್ಣಗಳನ್ನು ಬಳಸುತ್ತದೆ." },
  "Stops decorative animations and rotating profile effects.": { hi: "सजावटी एनिमेशन और घूमते प्रोफाइल प्रभाव रोकता है।", mr: "सजावटी अ‍ॅनिमेशन आणि फिरणारे प्रोफाइल प्रभाव थांबवते.", ta: "அலங்கார இயக்கங்கள் மற்றும் சுழலும் சுயவிவர விளைவுகளை நிறுத்தும்.", te: "అలంకార యానిమేషన్లు మరియు తిరిగే ప్రొఫైల్ ప్రభావాలను ఆపుతుంది.", kn: "ಅಲಂಕಾರಿಕ ಅನಿಮೇಶನ್‌ಗಳು ಮತ್ತು ತಿರುಗುವ ಪ್ರೊಫೈಲ್ ಪರಿಣಾಮಗಳನ್ನು ನಿಲ್ಲಿಸುತ್ತದೆ." },
  "Screen reader support": { hi: "स्क्रीन रीडर समर्थन", mr: "स्क्रीन रीडर समर्थन", ta: "திரைவாசிப்பு ஆதரவு", te: "స్క్రీన్ రీడర్ మద్దతు", kn: "ಸ್ಕ್ರೀನ್ ರೀಡರ್ ಬೆಂಬಲ" },
  "Adds clearer labels and hints for assistive technology.": { hi: "सहायक तकनीक के लिए स्पष्ट लेबल और संकेत जोड़ता है।", mr: "सहाय्यक तंत्रज्ञानासाठी स्पष्ट लेबले आणि सूचना जोडते.", ta: "உதவி தொழில்நுட்பத்திற்கான தெளிவான லேபிள்களையும் குறிப்புகளையும் சேர்க்கும்.", te: "సహాయక సాంకేతికత కోసం స్పష్టమైన లేబుళ్లు మరియు సూచనలను జోడిస్తుంది.", kn: "ಸಹಾಯಕ ತಂತ್ರಜ್ಞಾನಕ್ಕೆ ಸ್ಪಷ್ಟ ಲೇಬಲ್‌ಗಳು ಮತ್ತು ಸೂಚನೆಗಳನ್ನು ಸೇರಿಸುತ್ತದೆ." },
  "Large touch targets": { hi: "बड़े टच लक्ष्य", mr: "मोठे टच लक्ष्य", ta: "பெரிய தொடு பகுதிகள்", te: "పెద్ద టచ్ లక్ష్యాలు", kn: "ದೊಡ್ಡ ಸ್ಪರ್ಶ ಗುರಿಗಳು" },
  "Makes buttons easier to tap for motor accessibility.": { hi: "मोटर सुगम्यता के लिए बटन टैप करना आसान बनाता है।", mr: "मोटर सुलभतेसाठी बटणे टॅप करणे सोपे करते.", ta: "இயக்க அணுகலுக்காக பொத்தான்களைத் தட்ட எளிதாக்கும்.", te: "మోటార్ ప్రాప్యత కోసం బటన్లను ట్యాప్ చేయడం సులభం చేస్తుంది.", kn: "ಮೋಟಾರ್ ಪ್ರವೇಶಸೌಲಭ್ಯಕ್ಕಾಗಿ ಬಟನ್‌ಗಳನ್ನು ಸುಲಭವಾಗಿ ಟ್ಯಾಪ್ ಮಾಡಲು ಮಾಡುತ್ತದೆ." },
  "Reset accessibility settings": { hi: "सुगम्यता सेटिंग रीसेट करें", mr: "सुलभता सेटिंग्ज रीसेट करा", ta: "அணுகல்தன்மை அமைப்புகளை மீட்டமை", te: "ప్రాప్యత సెట్టింగ్‌లను రీసెట్ చేయండి", kn: "ಪ್ರವೇಶಸೌಲಭ್ಯ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಮರುಹೊಂದಿಸಿ" },
  "Restores default accessibility preferences for all pages": { hi: "सभी पेजों के लिए डिफ़ॉल्ट सुगम्यता प्राथमिकताएँ लौटाता है", mr: "सर्व पानांसाठी डीफॉल्ट सुलभता प्राधान्ये पुनर्संचयित करते", ta: "எல்லா பக்கங்களுக்கும் இயல்புநிலை அணுகல் விருப்பங்களை மீட்டமைக்கும்", te: "అన్ని పేజీలకు డిఫాల్ట్ ప్రాప్యత అభిరుచులను పునరుద్ధరిస్తుంది", kn: "ಎಲ್ಲ ಪುಟಗಳಿಗೆ ಡೀಫಾಲ್ಟ್ ಪ್ರವೇಶಸೌಲಭ್ಯ ಆದ್ಯತೆಗಳನ್ನು ಮರುಸ್ಥಾಪಿಸುತ್ತದೆ" },
  "Reset Accessibility Settings": { hi: "सुगम्यता सेटिंग रीसेट करें", mr: "सुलभता सेटिंग्ज रीसेट करा", ta: "அணுகல்தன்மை அமைப்புகளை மீட்டமை", te: "ప్రాప్యత సెట్టింగ్‌లను రీసెట్ చేయండి", kn: "ಪ್ರವೇಶಸೌಲಭ್ಯ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಮರುಹೊಂದಿಸಿ" },
  "Accessibility settings reset to defaults": { hi: "सुगम्यता सेटिंग डिफ़ॉल्ट पर रीसेट हुई", mr: "सुलभता सेटिंग्ज डीफॉल्टवर रीसेट झाल्या", ta: "அணுகல்தன்மை அமைப்புகள் இயல்புநிலைக்கு மீட்டமைக்கப்பட்டன", te: "ప్రాప్యత సెట్టింగ్‌లు డిఫాల్ట్‌లకు రీసెట్ అయ్యాయి", kn: "ಪ್ರವೇಶಸೌಲಭ್ಯ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಡೀಫಾಲ್ಟ್‌ಗೆ ಮರುಹೊಂದಿಸಲ್ಪಟ್ಟಿವೆ" },
