  "Save Location": { hi: "स्थान सहेजें", mr: "स्थान जतन करा", ta: "இருப்பிடம் சேமி", te: "స్థానాన్ని సేవ్ చేయండి", kn: "ಸ್ಥಳ ಉಳಿಸಿ" },
  "Volunteer Skills": { hi: "स्वयंसेवक कौशल", mr: "स्वयंसेवक कौशल्ये", ta: "தன்னார்வ திறன்கள்", te: "స్వచ్ఛంద సేవకుల నైపుణ్యాలు", kn: "ಸ್ವಯಂಸೇವಕ ಕೌಶಲ್ಯಗಳು" },
  "These skills are saved to your volunteer profile and used for need match scores.": { hi: "ये कौशल आपके स्वयंसेवक प्रोफाइल में सहेजे जाते हैं और जरूरत मिलान स्कोर में उपयोग होते हैं।", mr: "ही कौशल्ये तुमच्या स्वयंसेवक प्रोफाइलमध्ये जतन होतात आणि गरज जुळणी गुणांसाठी वापरली जातात.", ta: "இந்த திறன்கள் உங்கள் தன்னார்வ சுயவிவரத்தில் சேமிக்கப்பட்டு தேவை பொருத்த மதிப்பெண்களில் பயன்படுத்தப்படும்.", te: "ఈ నైపుణ్యాలు మీ స్వచ్ఛంద సేవకుల ప్రొఫైల్‌లో సేవ్ చేయబడి అవసర సరిపోలిక స్కోర్‌లకు ఉపయోగిస్తారు.", kn: "ಈ ಕೌಶಲ್ಯಗಳು ನಿಮ್ಮ ಸ್ವಯಂಸೇವಕ ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿ ಉಳಿದು ಅವಶ್ಯಕತೆ ಹೊಂದಾಣಿಕೆ ಅಂಕಗಳಿಗೆ ಬಳಸಲಾಗುತ್ತವೆ." },
  "Skill, for example medical, cooking, logistics": { hi: "कौशल, जैसे चिकित्सा, खाना बनाना, लॉजिस्टिक्स", mr: "कौशल्य, उदा. वैद्यकीय, स्वयंपाक, लॉजिस्टिक्स", ta: "திறன், உதா. மருத்துவம், சமையல், லாஜிஸ்டிக்ஸ்", te: "నైపుణ్యం, ఉదాహరణకు వైద్యం, వంట, లాజిస్టిక్స్", kn: "ಕೌಶಲ್ಯ, ಉದಾ. ವೈದ್ಯಕೀಯ, ಅಡುಗೆ, ಲಾಜಿಸ್ಟಿಕ್ಸ್" },
  "Saving...": { hi: "सहेजा जा रहा है...", mr: "जतन करत आहे...", ta: "சேமிக்கப்படுகிறது...", te: "సేవ్ అవుతోంది...", kn: "ಉಳಿಸಲಾಗುತ್ತಿದೆ..." },
