  "PDF ingest failed.": { hi: "PDF इनजेस्ट विफल।", mr: "PDF इनजेस्ट अयशस्वी.", ta: "PDF உட்கொள்வது தோல்வியடைந்தது.", te: "PDF ఇంజెస్ట్ విఫలమైంది.", kn: "PDF ಇಂಜೆಸ್ಟ್ ವಿಫಲವಾಗಿದೆ." },
  "Upload a CSV file or paste CSV content.": { hi: "CSV फ़ाइल अपलोड करें या CSV सामग्री चिपकाएँ।", mr: "CSV फाइल अपलोड करा किंवा CSV मजकूर पेस्ट करा.", ta: "CSV கோப்பை பதிவேற்றவும் அல்லது CSV உள்ளடக்கத்தை ஒட்டவும்.", te: "CSV ఫైల్ అప్‌లోడ్ చేయండి లేదా CSV కంటెంట్ అతికించండి.", kn: "CSV ಫೈಲ್ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಅಥವಾ CSV ವಿಷಯ ಅಂಟಿಸಿ." },
  "CSV processed": { hi: "CSV संसाधित", mr: "CSV प्रक्रिया झाले", ta: "CSV செயலாக்கப்பட்டது", te: "CSV ప్రాసెస్ అయింది", kn: "CSV ಪ್ರಕ್ರಿಯೆಗೊಂಡಿದೆ" },
  "CSV submit failed.": { hi: "CSV सबमिट विफल।", mr: "CSV सबमिट अयशस्वी.", ta: "CSV சமர்ப்பிப்பு தோல்வியடைந்தது.", te: "CSV సమర్పణ విఫలమైంది.", kn: "CSV ಸಲ್ಲಿಕೆ ವಿಫಲವಾಗಿದೆ." },
  "CSV source added to most recent need.": { hi: "CSV स्रोत हाल की जरूरत में जोड़ा गया।", mr: "CSV स्रोत अलीकडील गरजेत जोडला.", ta: "CSV மூலம் சமீபத்திய தேவையில் சேர்க்கப்பட்டது.", te: "CSV మూలం ఇటీవలి అవసరానికి జోడించబడింది.", kn: "CSV ಮೂಲವನ್ನು ಇತ್ತೀಚಿನ ಅವಶ್ಯಕತೆಗೆ ಸೇರಿಸಲಾಗಿದೆ." },
  "No needs exist. Create a need first, then add CSV source.": { hi: "कोई जरूरत मौजूद नहीं। पहले जरूरत बनाएँ, फिर CSV स्रोत जोड़ें।", mr: "गरजा नाहीत. आधी गरज तयार करा, मग CSV स्रोत जोडा.", ta: "தேவைகள் இல்லை. முதலில் தேவையை உருவாக்கி, பின்னர் CSV மூலத்தை சேர்க்கவும்.", te: "అవసరాలు లేవు. ముందుగా అవసరాన్ని సృష్టించి, తర్వాత CSV మూలం జోడించండి.", kn: "ಅವಶ್ಯಕತೆಗಳಿಲ್ಲ. ಮೊದಲು ಅವಶ್ಯಕತೆ ರಚಿಸಿ, ನಂತರ CSV ಮೂಲ ಸೇರಿಸಿ." },
  "Admin account is not assigned to a branch. Please ask the owner to assign a managed branch before creating needs.": { hi: "Admin खाते को शाखा नहीं सौंपी गई है। जरूरतें बनाने से पहले मालिक से प्रबंधित शाखा सौंपने को कहें।", mr: "Admin खात्याला शाखा नेमलेली नाही. गरजा तयार करण्यापूर्वी मालकाला व्यवस्थापित शाखा नेमण्यास सांगा.", ta: "Admin கணக்கிற்கு கிளை ஒதுக்கப்படவில்லை. தேவைகள் உருவாக்குமுன் உரிமையாளரிடம் நிர்வகிக்கும் கிளையை ஒதுக்கச் சொல்லவும்.", te: "Admin ఖాతాకు శాఖ కేటాయించలేదు. అవసరాలు సృష్టించే ముందు యజమానిని నిర్వహిత శాఖ కేటాయించమని అడగండి.", kn: "Admin ಖಾತೆಗೆ ಶಾಖೆ ನಿಯೋಜಿಸಲಾಗಿಲ್ಲ. ಅವಶ್ಯಕತೆಗಳನ್ನು ರಚಿಸುವ ಮೊದಲು ಮಾಲೀಕರಿಗೆ ನಿರ್ವಹಿತ ಶಾಖೆ ನಿಯೋಜಿಸಲು ಕೇಳಿ." },
  "Lifecycle actions, status transitions, and feedback": { hi: "जीवनचक्र कार्रवाई, स्थिति बदलाव और प्रतिक्रिया", mr: "जीवनचक्र कृती, स्थिती बदल आणि अभिप्राय", ta: "வாழ்க்கைச்சுழற்சி செயல்கள், நிலை மாற்றங்கள் மற்றும் கருத்து", te: "జీవనచక్ర చర్యలు, స్థితి మార్పులు మరియు అభిప్రాయం", kn: "ಜೀವಚಕ್ರ ಕ್ರಮಗಳು, ಸ್ಥಿತಿ ಬದಲಾವಣೆಗಳು ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆ" },
  "Org ID": { hi: "संगठन ID", mr: "संस्था ID", ta: "அமைப்பு ID", te: "సంస్థ ID", kn: "ಸಂಸ್ಥೆ ID" },
