  "Unable to update status": { hi: "स्थिति अपडेट नहीं हो सकी", mr: "स्थिती अपडेट करता आली नाही", ta: "நிலையை புதுப்பிக்க முடியவில்லை", te: "స్థితిని నవీకరించలేకపోయాం", kn: "ಸ್ಥಿತಿ ನವೀಕರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ" },
  "Please select a rating from 1 to 5 stars.": { hi: "कृपया 1 से 5 सितारों में रेटिंग चुनें।", mr: "कृपया 1 ते 5 तार्‍यांमधून रेटिंग निवडा.", ta: "1 முதல் 5 நட்சத்திரங்களில் மதிப்பீட்டை தேர்வு செய்யவும்.", te: "దయచేసి 1 నుండి 5 నక్షత్రాల రేటింగ్ ఎంచుకోండి.", kn: "ದಯವಿಟ್ಟು 1 ರಿಂದ 5 ನಕ್ಷತ್ರಗಳಲ್ಲಿ ರೇಟಿಂಗ್ ಆಯ್ಕೆಮಾಡಿ." },
