  "Your data has changed.": { hi: "आपका डेटा बदल गया है।", mr: "तुमचा डेटा बदलला आहे.", ta: "உங்கள் தரவு மாறியுள்ளது.", te: "మీ డేటా మారింది.", kn: "ನಿಮ್ಮ ಡೇಟಾ ಬದಲಾಗಿದೆ." },
